INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-tariffs-14-economies-section-301', 'trump-administration-proposes-section-301-tariffs-14-economies-china-eu-india-excess-capacity', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Trump administration proposes new tariffs on 14 economies, including China, the EU and India', 'The U.S. Trade Representative announced the duties on Wednesday, Nov. 25, after an eight-month probe into factory overcapacity, using a trade law that was not part of the Supreme Court ruling against the earlier global tariffs.', 'The Trump administration on Wednesday, Nov. 25, announced plans for new tariffs on 14 major trading partners, including China, the European Union and India, Al Jazeera reported.

The Office of the U.S. Trade Representative announced the duties after an eight-month investigation, begun in March, into what it calls structural excess capacity: subsidies that it says help foreign factories overproduce, according to Al Jazeera.

## Who is on the list

The 14 economies named are China, Bangladesh, Cambodia, the European Union, India, Indonesia, Japan, South Korea, Malaysia, Singapore, Switzerland, Taiwan, Thailand and Vietnam, Al Jazeera reported. Mexico and Norway were also investigated but were spared for now.

China faces a proposed 20% excess capacity tariff on top of roughly 25% in duties from Trump''s first term, and Vietnam also faces a proposed 20% rate, according to Al Jazeera. Rates for most of the other economies were not released ahead of their publication in the Federal Register, the outlet said, citing a senior official who spoke to Reuters. That official said the new duties would not be stacked on top of the existing forced labor tariffs.

## A different legal footing

The new duties rest on Section 301 of the Trade Act of 1974, the law Trump used for China tariffs in his first term, Al Jazeera reported. In February, the Supreme Court ruled that the emergency powers law behind the April 2025 "Liberation Day" tariffs did not allow trade tariffs.

Trade policy expert Dmitry Grozoubinski told Al Jazeera the new tariffs would certainly be challenged in court but are probably the most legally robust of Trump''s tariffs. Beijing rejects the accusation of overcapacity and says its exports are competitive, the outlet reported.

## Politics ahead

Democrats take control of both chambers of Congress in January, and a Reuters/Ipsos poll taken after the midterms found 62% of respondents would support efforts to scrap trade tariffs, according to Al Jazeera. Trump can veto any bill that tries to roll them back.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Container_ship_NYK_Themis_at_the_Port_of_Los_Angeles.jpg/1280px-Container_ship_NYK_Themis_at_the_Port_of_Los_Angeles.jpg', 'The container ship NYK Themis at the Port of Los Angeles (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 9, 1, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
