INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-birthright-second-order-cooper', 'judge-christopher-cooper-blocks-trump-second-birthright-citizenship-order-class', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'A second federal judge blocks Trump''s narrower birthright citizenship order', 'D.C. District Judge Christopher Cooper granted a preliminary injunction on Wednesday, Nov. 25, and certified a class, ABC News reported. The Supreme Court struck down the first order in June.', 'A federal judge in Washington, D.C., on Wednesday, Nov. 25, blocked President Trump''s second executive order restricting birthright citizenship, ABC News reported. It is the second federal judge to block the order, according to GovBrief''s daily roundup, which cited The Hill.

U.S. District Judge Christopher Cooper, an Obama appointee, granted a preliminary injunction and granted class-action status to the group that brought the suit, according to ABC News. The block applies to members of the certified class.

## What the order does

Trump signed the narrower order in August, after the Supreme Court in June struck down his first-day order that sought to end birthright citizenship altogether, ABC News reported. The new order directed federal agencies not to grant citizenship to three groups of U.S.-born children: those whose parents worked for foreign governments or other organizations without diplomatic immunity, those born through commercial surrogacy, and those with a parent who is a suspected gang member or potential terrorist.

## The ruling

Cooper wrote that the Constitution''s Citizenship Clause promises citizenship to practically all children born in the United States, and that the Supreme Court kept that promise when it struck down the first order, according to ABC News. He wrote that the government cannot carve out new exceptions.

ABC News said it had asked the Justice Department and the White House for comment. No response was reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/E._Barrett_Prettyman_U.S._Courthouse.JPG/1280px-E._Barrett_Prettyman_U.S._Courthouse.JPG', 'The E. Barrett Prettyman U.S. Courthouse in Washington, home of the federal district court for D.C. (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 8, 0, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261126-birthright-second-order-cooper-src1', 'bd-20261126-birthright-second-order-cooper', 'Judge blocks latest Trump effort to restrict birthright citizenship', 'https://www.goodmorningamerica.com/news/story/judge-blocks-latest-trump-effort-restrict-birthright-citizenship-138451919', 'ABC News (Good Morning America)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-26T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-26. Editor to confirm.', 'newsroom-assistant', '2026-11-26T11:00:00.000Z');
