INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-medicare-noncitizen-eligibility-feb-2027', 'social-security-medicare-eligibility-refugees-asylum-coverage-may-end-february-1-2027', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Refugees and asylum grantees on Medicare face loss of coverage on Feb. 1, 2027, under the 2025 budget law', 'Social Security began applying the new eligibility rules in mid-November and is notifying enrollees whose status it cannot confirm. Newsweek reported about 32,000 people are expected to lose coverage.', 'Some legal immigrants enrolled in Medicare, including refugees and people granted asylum, could lose their coverage on Monday, Feb. 1, 2027, under the budget law Congress passed in July 2025, according to the Social Security Administration and Newsweek.

In a letter to advocates dated Tuesday, Nov. 10, Social Security said it would begin applying the new requirements under Section 71201 of Public Law 119-21 to Medicare applications and enrollments, and would notify current beneficiaries whose eligibility it cannot confirm. Their coverage may end Feb. 1, 2027, unless they establish eligibility within the time given in the notice, the agency said.

## Who remains eligible

Under the law, Medicare is limited to U.S. citizens and nationals, lawful permanent residents, Cuban-Haitian entrants and migrants living in the U.S. under the Compacts of Free Association, according to the agency. Newsweek reported that refugees, asylum grantees, people with Temporary Protected Status and others were removed from the list. Social Security said the changes do not affect Social Security benefits themselves.

## How many people

Newsweek reported on Friday, Nov. 13, that the Centers for Medicare and Medicaid Services estimated about 32,000 people would lose coverage. The Medicare Rights Center told the outlet the changes will cause immense harm.

## What recipients can do

Social Security tells people who get a notice to respond by the deadline on it and to send proof of citizenship or eligible status, either by uploading documents through a my Social Security account or by visiting a local office. People who gain eligible status later can apply again, the agency said.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Social_Security_Administration_Building_-_panoramio.jpg/1280px-Social_Security_Administration_Building_-_panoramio.jpg', 'A Social Security Administration building (file photo). Panoramio photo via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 6, 0, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261126-medicare-noncitizen-eligibility-feb-2027-src1', 'bd-20261126-medicare-noncitizen-eligibility-feb-2027', 'Changes to Medicare Eligibility Requirements', 'https://www.ssa.gov/news/en/advocates/2026-11-10.html', 'Social Security Administration', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-26T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-26. Editor to confirm.', 'newsroom-assistant', '2026-11-26T11:00:00.000Z');
