INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-jets-beat-bruins-4-2', 'jets-beat-bruins-4-2-td-garden-kyle-connor-three-points-barron-winner', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Jets beat Bruins 4-2 at TD Garden as Kyle Connor collects three points', 'Morgan Barron scored the go-ahead goal late in the second period on Wednesday, Nov. 25. Boston fell to 15-8-1 and hosts Toronto on Friday, Nov. 27.', 'The Winnipeg Jets beat the Boston Bruins 4-2 at TD Garden on Wednesday, Nov. 25, with Kyle Connor scoring once and setting up two more goals, NHL.com and the Associated Press reported.

## How it went

Connor opened the scoring 1:05 into the game, and Morgan Geekie tied it on a power play at 6:11 of the first period, according to NHL.com. Josh Morrissey put Winnipeg back in front with a slap shot late in the first. Fraser Minten tied it 2-2 midway through the second by redirecting a Mason Lohrei shot from the point.

Morgan Barron scored the go-ahead goal at 17:53 of the second, poking in a rebound after Jeremy Swayman stopped Mario Ferraro''s shot, NHL.com reported. Mark Scheifele added an empty-net goal with 1:12 left.

Nico Daws made 21 saves for Winnipeg, and Swayman made 14 for Boston, according to NHL.com. Tanner Jeannot and Tyrel Bauer fought in the first period, the AP reported.

## Where they stand

Boston fell to 15-8-1 after winning its two previous games, NHL.com reported. The game was the second of a six-game homestand, the Bruins'' longest of the season, according to the AP. Winnipeg improved to 13-9-4 and has earned points in 10 of its past 11 games. Connor reached 20 goals in 26 games, the third-fastest pace in Jets franchise history, NHL.com said. Geekie said afterward the Bruins made too many mistakes.

The Bruins host the Toronto Maple Leafs on Friday, Nov. 27.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Zakim_Bridge_and_TD_Garden.JPG/1280px-Zakim_Bridge_and_TD_Garden.JPG', 'The Zakim Bridge and TD Garden in Boston (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 8, 0, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
