INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-knicks-beat-cavaliers-121-102', 'knicks-beat-cavaliers-121-102-sixth-straight-alvarado-nba-cup', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Knicks rally past Cavaliers 121-102 for a sixth straight win and stay alive in the NBA Cup', 'New York outscored Cleveland 39-17 in the fourth quarter at Madison Square Garden on Wednesday, Nov. 25, behind a season-high 21 points from Jose Alvarado.', 'The New York Knicks pulled away from the Cleveland Cavaliers in the fourth quarter on Wednesday, Nov. 25, winning 121-102 at Madison Square Garden for their sixth straight victory, the Associated Press reported.

The defending NBA Cup champions would have been eliminated from Cup title contention with a loss, according to the AP.

## The fourth quarter

Cleveland led by 11 points late in the first half, but New York outscored the Cavaliers 39-17 in the final quarter, the AP reported. Jose Alvarado hit back-to-back 3-pointers in the run and finished with a season-high 21 points.

Mikal Bridges added 19 points and Jalen Brunson scored 19 on 6-of-22 shooting, according to the AP. Josh Hart had 15 points, 12 assists and seven rebounds. Karl-Anthony Towns had 12 points and 10 rebounds, extending his season-opening streak of double-doubles to 17 games.

Donovan Mitchell scored 30 points and James Harden added 28 for Cleveland, the AP reported.

## Records and injuries

The Knicks improved to 12-6 and the Cavaliers fell to 9-10, according to the AP. New York played without OG Anunoby, who has a left calf strain, and Cleveland was without Evan Mobley because of a toe injury.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Madison_Square_Garden%2C_February_2013.jpg/1280px-Madison_Square_Garden%2C_February_2013.jpg', 'Madison Square Garden in New York, February 2013 (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 6, 0, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
