INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261126-timberwolves-beat-thunder-113-106', 'timberwolves-beat-thunder-113-106-jaden-mcdaniels-32-nba-cup-3-0', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Timberwolves beat the Thunder 113-106 in Oklahoma City to go 3-0 in NBA Cup play', 'Jaden McDaniels scored 32 points on Wednesday, Nov. 25, and Minnesota has won 10 of its last 12. Shai Gilgeous-Alexander also scored 32 for Oklahoma City.', 'The Minnesota Timberwolves beat the Oklahoma City Thunder 113-106 at Paycom Center on Wednesday, Nov. 25, improving to 3-0 in NBA Cup group play, the Associated Press reported.

Jaden McDaniels led Minnesota with 32 points and 10 rebounds, making 11 of 15 shots, including four of five 3-pointers, according to the AP.

## The turn in the third

Oklahoma City led 53-47 at halftime after a 37-21 second quarter and later went up 73-63, the AP reported. Minnesota answered with a 24-10 run to close the third quarter, capped by a 26-foot McDaniels shot at the buzzer for an 87-83 lead.

Ajay Mitchell''s 3-pointer pulled the Thunder within 105-104, but Minnesota held on, according to the AP. The Timberwolves made 17 of 39 3-pointers and outrebounded Oklahoma City 40-30.

Shai Gilgeous-Alexander scored 32 points and Mitchell added 25 for the Thunder, the AP reported. LaMelo Ball scored 19 for Minnesota before leaving with an ankle injury in the final minutes.

## Records

Minnesota improved to 14-5 and has won 10 of its last 12 games, according to the AP. Oklahoma City fell to 10-9 and has lost six of its last nine.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Paycom_Center_OKC.jpg/1280px-Paycom_Center_OKC.jpg', 'Paycom Center in Oklahoma City (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-26.sql', 5, 0, 'newsroom-assistant', '2026-11-26T11:00:00.000Z', '2026-11-26T11:00:00.000Z');
